def construct():
    n = 19
    p = 19
    # Quadratic residues mod 19
    Q = set()
    for i in range(1, p):
        if (i * i) % p in [1, 4, 9, 16, 6, 17, 11, 7, 5]: # Just compute directly
            pass
    Q = set()
    for i in range(1, p):
        Q.add((i * i) % p)
    Q.discard(0)
    
    # Construct the generator vector
    # The QR code is the cyclic code generated by the vector v where v_i = 1 if i in Q
    # However, standard QR code construction uses the idempotent.
    # For p=19, let's just generate the span of shifts of v.
    v = 0
    for i in Q:
        v |= 1 << i
        
    # Generate all shifts of v
    basis = []
    for shift in range(n):
        word = (v << shift) % (2**n - 1)
        # Reduce to n bits
        # Actually, cyclic shift
        word = ((v << shift) | (v >> (n - shift))) & ((1 << n) - 1)
        basis.append(word)
        
    # Find a linear basis for these words
    # Use Gaussian elimination
    mat = []
    for w in basis:
        mat.append(w)
        
    # Gaussian elimination over GF(2)
    # We want to find the rank and a basis
    rank = 0
    basis_words = []
    for i in range(n):
        # Find a word with bit i set
        found = -1
        for j in range(len(mat)):
            if mat[j] & (1 << i):
                found = j
                break
        if found == -1:
            continue
        # Swap
        mat[i], mat[found] = mat[found], mat[i]
        # Eliminate
        for j in range(len(mat)):
            if j != i and (mat[j] & (1 << i)):
                mat[j] ^= mat[i]
        basis_words.append(mat[i])
        rank += 1
        
    # Generate all codewords
    codewords = [0]
    for b in basis_words:
        new_codewords = []
        for c in codewords:
            new_codewords.append(c)
            new_codewords.append(c ^ b)
        codewords = new_codewords
        
    # Shorten the code by position 0
    # Keep only codewords with bit 0 = 0
    shortened = []
    for c in codewords:
        if (c & 1) == 0:
            # Remove bit 0
            c_short = c >> 1
            shortened.append(c_short)
            
    return shortened
